import{z as n,x as d,o,c as A,q as E,j as i,D as r,d as e,s as B,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"固件安全","description":"","frontmatter":{"title":"固件安全","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/firmware-security.md","filePath":"cs/firmware-security.md","lastUpdated":1791413859000}'),p={name:"cs/firmware-security.md"};function c(S,a,m,C,h,P){const s=d("Mermaid");return o(),A("div",null,[a[2]||(a[2]=E('<h1 id="固件安全" tabindex="-1">固件安全 <a class="header-anchor" href="#固件安全" aria-label="Permalink to &quot;固件安全&quot;">​</a></h1><div class="epigraph"><p>固件先于操作系统，更新通道常弱：无签名、无回滚保护、管理引擎不透明。固件完整是 TCB 的底，补丁窗口与供应链在此最痛。</p><footer>—— 据 NIST SP 800-193；UEFI 对胶囊更新的讨论；对照 Intel 管理引擎的公开分析点名</footer></div><p>上一课<a href="/cs/secure-boot-chain">安全启动</a>假定固件是锚的一部分。缺口是<strong>固件自己的更新与植入</strong>。本课讲签名更新、防回滚、带外管理，不写刷入恶意固件的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BIOS 密码空、更新不验签、可回滚到已撤销版本、BMC 挂默认口令在生产网。固件在 OS 之下：植入后重装系统、换盘都清不掉，还能在启动早期钩住 OS 载入的内核。缺口是：签名、版本单调、带外管理面与主机隔离。</p><p><span class="marginnote">直觉类比：固件像房子的地基——重装系统像重新粉刷房间，换硬盘像换家具，都动不到地基。固件住在 SPI 闪存和管理引擎里，操作系统开机后才开始看世界，自然扫不到比它更早醒来的东西。</span></p><h3 id="供应" tabindex="-1">供应 <a class="header-anchor" href="#供应" aria-label="Permalink to &quot;供应&quot;">​</a></h3><p>出厂植入不在 OS 扫描器视野。SBOM 对固件更弱：SPI 镜像混着多供应商闭源模块，组件清单难完整（回 <a href="/cs/sbom-reproducible-builds">SBOM</a>）。采购能要的是签名更新承诺与披露渠道，不是源码。</p><p><span class="marginnote">SP 800-193 平台固件弹性。禁止固件植入教程。功耗分析下一课换物理侧信道。UEFI 撤销靠 dbx 拒绝库：BootHole（CVE-2020-10713）后批量撤销引导器；SP 800-193 三步是 protect/detect/recover。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新通道三件套：胶囊验签（平台根钥锚在硬件）、防回滚（版本号单调计数或熔丝）、恢复镜像（双分区或只读备份，对应 recover）。对照主机补丁与固件补丁周期——固件窗口以季度计，dbx 撤销与微码更新也要入周期。带外管理（BMC/IPMI、管理引擎）有独立 IP 与独立 OS，常漏在资产清单外；管理网分段。下一课 DPA。</p><p><span class="marginnote">术语翻译：防回滚就是「让旧版本再也装不回去」的手段：要么在 NVRAM 里记一个只增不减的版本计数器，要么把版本「烧」进一次性熔丝。没有它，攻击者把打过补丁的固件换回有漏洞的旧版，验签照样通过。</span></p>',13)),(o(),i(l,null,{default:r(()=>[B(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E5%9B%BA%E4%BB%B6%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20SIG%5B%22%E5%BF%85%E9%A1%BB%E9%AA%8C%E7%AD%BE%22%5D%0A%20%20UPD%20--%3E%20RB%5B%22%E9%98%B2%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20OOB%5B%22%E5%B8%A6%E5%A4%96%E7%AE%A1%E7%90%86%22%5D%20--%3E%20SEG%5B%22%E4%B8%8E%E7%94%9F%E4%BA%A7%E7%BD%91%E5%88%86%E6%AE%B5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("启动链逐级验证：boot ROM 验 SoC 固件，固件验引导器，"),t("a",{href:"/cs/tpm-measured-boot"},"TPM"),e(" 把各阶段度量进 PCR——固件不能自证，只能向上锚定硬件根（掩膜 ROM、熔丝）。失败模式：验证跳线被短接、NVRAM 变量被改、SPI 芯片离线重写；远程攻击者到不了这些，物理接触者可以——那是下一课的威胁模型。TCB 含固件。供应链任一环失守都写入底座，ME/PSP 这类不透明管理引擎因此被点名。物理攻击下一课假设盒子在手。")],-1)),(o(),i(l,null,{default:r(()=>[B(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20RT%5B%22%E7%A1%AC%E4%BB%B6%E6%A0%B9%3A%20%E6%8E%A9%E8%86%9C%20ROM%20%2F%20%E7%86%94%E4%B8%9D%22%5D%20--%3E%7C%22%E9%AA%8C%E7%AD%BE%22%7C%20S%5B%22SoC%20%E5%9B%BA%E4%BB%B6%22%5D%0A%20%20S%20--%3E%7C%22%E9%AA%8C%E7%AD%BE%22%7C%20BL%5B%22%E5%BC%95%E5%AF%BC%E5%99%A8%22%5D%0A%20%20BL%20--%3E%7C%22%E9%AA%8C%E7%AD%BE%22%7C%20OS%5B%22%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%86%85%E6%A0%B8%22%5D%0A%20%20S%20--%3E%7C%22%E5%BA%A6%E9%87%8F%E8%BF%9B%20PCR%22%7C%20T%5B%22TPM%22%5D%0A%20%20BL%20--%3E%7C%22%E5%BA%A6%E9%87%8F%E8%BF%9B%20PCR%22%7C%20T%0A%20%20OS%20--%3E%7C%22%E5%BA%A6%E9%87%8F%E8%BF%9B%20PCR%22%7C%20T%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">常见误区：初学者以为「重装系统就能清掉木马」。对 OS 之下的固件植入不成立：重装只覆盖磁盘上的系统分区，SPI 闪存里的固件原样保留，还能在启动早期钩住新内核。清底要走固件恢复流程（对应 SP 800-193 的 recover），不是重装。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写刷机攻击。功耗分析 DPA 下一课。本课只点名管理引擎的 TCB 地位，不评其内部实现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>启动链含固件；固件更新必须验签。</li><li>防回滚与带外面是合同。</li><li>OS 扫描看不见出厂植入。</li><li>下一课功耗分析。</li><li>出处：NIST SP 800-193；UEFI；Anderson。</li></ul>',5))])}const D=n(p,[["render",c]]);export{f as __pageData,D as default};
